import { _decorator, Component, Node, Sprite, SpriteFrame, UITransform } from 'cc';
import { GRID_COLS, GRID_ROWS, TILE_W, TILE_H, TILE_IMG_W, TILE_IMG_H, TILE_VISUAL_OFFSET_Y, gridToLocal } from '../Config/GridConfig';

const { ccclass, property } = _decorator;

@ccclass('GridView')
export class GridView extends Component {
    // 在编辑器里拖入单格草地图
    @property(SpriteFrame) tileSpriteFrame: SpriteFrame = null!;

    // HallScene 会调用这个方法
    public createMap(): void {
        if (!this.tileSpriteFrame) return;

        const tileNodes: { node: Node, y: number }[] = [];

        for (let y = 0; y < GRID_ROWS; y++) {
            for (let x = 0; x < GRID_COLS; x++) {
                const tileNode = new Node(`Tile_${x}_${y}`);
                const sprite = tileNode.addComponent(Sprite);
                sprite.spriteFrame = this.tileSpriteFrame;
                sprite.sizeMode = Sprite.SizeMode.CUSTOM;

                tileNode.getComponent(UITransform)!.setContentSize(TILE_IMG_W, TILE_IMG_H);

                const pos = gridToLocal(x, y);
                tileNode.setPosition(pos.x, pos.y + TILE_VISUAL_OFFSET_Y);
                this.node.addChild(tileNode); // 把 Tile 挂到 MapLayer 下

                tileNodes.push({ node: tileNode, y: pos.y });
            }
        }

        // 2.5D 层级遮挡排序
        tileNodes.sort((a, b) => b.y - a.y);
        for (let i = 0; i < tileNodes.length; i++) {
            tileNodes[i].node.setSiblingIndex(i);
        }
    }
}